-- Jambix AIO 1.7.6: what skinning a corpse gives (modules/skinning_data.lua,
-- generated by tools/jcheck/skinning_extract.js from CMaNGOS's Classic tables
-- and the client's Item.db2), and the art pack's icon for every item in it.

if not jtest then package.path = "scripts/?.lua;" .. package.path end

local function assert_eq(got, want, label)
    if got ~= want then
        error(string.format("%s: expected %s, got %s", label, tostring(want), tostring(got)), 2)
    end
end

local D = require("jambix_aio/modules/skinning_data")
local pack = require("jambix_aio/modules/esp/art_pack")

local T = {}

T[#T + 1] = { "the file: 924 creatures in 774 tables, 48 items (Pristine Leather the 48th)", function()
    assert_eq(D.count.npcs, 924, "creatures")
    assert_eq(D.count.tables, 774, "tables")
    assert_eq(D.count.items, 48, "items")
    local n = 0
    for _ in pairs(D.loot) do n = n + 1 end
    assert_eq(n, D.count.tables, "every table written")
    assert(D.source:find("cmangos/classic-db", 1, true), "says where it came from: " .. D.source)
end }

T[#T + 1] = { "known kinds: a Winter Wolf, the Large Loch Crocolisk, The Beast", function()
    local wolf = D.loot[1131]
    assert_eq(#wolf, 2, "two items")
    assert_eq(wolf[1][1], 2934, "Ruined Leather Scraps first, the likelier")
    assert_eq(wolf[1][2], 60.3, "60.3%")
    assert_eq(wolf[2][1], 2318, "then Light Leather")
    assert_eq(wolf[2][2], 39.7, "39.7%")
    assert_eq(wolf[1][3], nil, "one of each: no count written")

    local croc = D.loot[2476]
    assert_eq(croc[2][1], 2318, "Light Leather")
    assert_eq(croc[2][3], 1, "one")
    assert_eq(croc[2][4], 2, "to two")

    local beast = D.loot[10430]
    assert_eq(beast[3][1], 12731, "Pristine Hide of the Beast")
    assert_eq(D.items[12731].quality, 4, "an epic")
    assert_eq(beast[1][3], 4, "Rugged Leather four")
    assert_eq(beast[1][4], 6, "to six")
end }

T[#T + 1] = { "a kind that shares another's table: Longsnout skins as Princess does", function()
    assert_eq(D.alias[119], 330, "Longsnout -> Princess's table")
    assert(D.loot[330], "which is written")
    assert_eq(D.loot[119], nil, "and not copied")
end }

T[#T + 1] = { "every table most likely first; most add up to 100%, none to nothing", function()
    local hundred, total = 0, 0
    for id, list in pairs(D.loot) do
        total = total + 1
        assert(#list >= 1, "table " .. id .. " has items")
        local sum = 0
        for i = 1, #list do
            sum = sum + list[i][2]
            assert(list[i][2] > 0, "table " .. id .. ": a chance above nothing")
            if i > 1 then assert(list[i][2] <= list[i - 1][2], "table " .. id .. " sorted") end
        end
        if sum >= 99 and sum <= 101 then hundred = hundred + 1 end
    end
    assert(hundred >= total - 42, "one roll each, but for the dragons' and bosses': " .. hundred .. " of " .. total)
end }

T[#T + 1] = { "every item has a name, a quality, the game's icon, and its cell in the art pack", function()
    local n = 0
    for id, item in pairs(D.items) do
        n = n + 1
        assert(type(item.name) == "string" and item.name ~= "", "item " .. id .. " named")
        assert(type(item.quality) == "number", item.name .. ": quality")
        assert(type(item.icon) == "number" and item.icon > 0, item.name .. ": icon")
        assert(pack.cells["item." .. id], item.name .. ": no art cell item." .. id)
    end
    assert_eq(n, D.count.items, "all of them")
    assert_eq(D.items[2318].name, "Light Leather", "Light Leather")
    assert_eq(D.items[2318].icon, 134252, "its icon in the bags (Item.db2)")
    for _, list in pairs(D.loot) do
        for i = 1, #list do assert(D.items[list[i][1]], "item " .. list[i][1] .. " described") end
    end
end }

-- 1.7.6: "Let's add Mobs that when skined also give pristine".
T[#T + 1] = { "pristine: 43 creatures, QuestieDB's 41 and two from the player's own skins; Pristine Leather green", function()
    assert_eq(D.count.pristine, 43, "creatures")
    local n = 0
    for npc, list in pairs(D.pristine) do
        n = n + 1
        assert(#list >= 1, "creature " .. npc .. " has an item")
        for i = 1, #list do
            local id = list[i]
            assert(id == 249427 or id == 249428 or id == 249429, "creature " .. npc .. ": a Pristine item, not " .. id)
            assert(D.items[id], "item " .. id .. " described")
        end
    end
    assert_eq(n, D.count.pristine, "every one written")
    assert(D.pristine_source:find("QuestieDB", 1, true), "says where it came from: " .. D.pristine_source)
    assert_eq(D.pristine[157][1], 249427, "Goretusk (QuestieDB)")
    assert_eq(D.pristine[3244][1], 249427, "Greater Plainstrider (QuestieDB)")
    assert_eq(D.pristine[213][1], 249427, "Starving Dire Wolf (your skins)")
    assert_eq(D.pristine[277645][1], 249427, "Gray Fox, Forever's own (your skins)")
    assert_eq(D.loot[277645], nil, "which Classic's tables never had")
    assert_eq(D.pristine[1131], nil, "a Winter Wolf: never seen")
    local leather = D.items[249427]
    assert_eq(leather.name, "Pristine Leather", "named")
    assert_eq(leather.quality, 2, "an uncommon")
    assert_eq(leather.icon, 348551, "its icon in the bags (Item.db2)")
    assert(pack.cells["item.249427"], "and its cell in the art pack")
end }

return T
